/* Help tooltip */
.label-row { display: flex; align-items: center; gap: 0.4rem; margin-top: 0.75rem; }
.label-row label { margin-top: 0; }
.help { position: relative; display: inline-flex; }
.help-icon:focus-visible { outline: 2px solid #1d4ed8; outline-offset: 2px; }
.tooltip {
  position: absolute; left: 50%; bottom: calc(100% + 8px); transform: translateX(-50%);
  z-index: 10; width: max-content; max-width: min(240px, 80vw);
  padding: 0.4rem 0.6rem; border-radius: 4px; background: #1d1f23; color: white;
  font-size: 0.85rem; font-weight: 400; line-height: 1.3;
  visibility: hidden; opacity: 0; transition: opacity 0.15s;
}
.tooltip::after { /* arrow */
  content: ""; position: absolute; left: 50%; top: 100%; transform: translateX(-50%);
  border: 6px solid transparent; border-top-color: #1d1f23;
}
.tooltip.below { bottom: auto; top: calc(100% + 8px); }
.tooltip.below::after { top: auto; bottom: 100%; border-top-color: transparent; border-bottom-color: #1d1f23; }
.tooltip.visible { visibility: visible; opacity: 1; }
